// The relations of a model to the entities nearest to it by their vectors, `generate-relation --nearest`:
// `GET /recipe/{id}/similar` lists the other recipes ordered by the distance of their vector to the vector of the
// recipe. The vectors are already in the database, the relation needs no embedder: the children are selected with
// their similarity to the vector of the parent, along the `near` column of the `ListQuery` generated by the search of
// the child (see search.rs), the most similar first or sorted by `sort`, the parent left out when the child is the parent.
use std::fs;
use std::io::{BufRead, Error, Write};
use std::path::{Path, PathBuf};

use syn::spanned::Spanned;

use super::search::{has_word, is_dense_vector};
use super::{
    add_relation_field, confirm, crate_module, declaration_hint, field_ident, highlight, model_structs, parse_model_file, pluralize, sort_columns, source_path, success, to_snake_case,
    warning, with_merged_root, write_source, ModulePaths, Relation, RelationFiles, OPENAPI_DERIVES,
};

// The vector columns a relation compares
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Nearest {
    // the vector column of the parent, `embedding`
    pub(crate) column: String,
    // the vector column of the child its `near` filter orders by, the one of the parent for a self relation
    pub(crate) child_column: String,
}

// The last segment of the route by default: `similar` for the recipes of a recipe, `nearest_wines` for its wines
pub(crate) fn default_name(parent: &str, child: &str) -> String {
    if parent == child {
        "similar".to_string()
    } else {
        format!("nearest_{}", pluralize(&to_snake_case(child)))
    }
}

// The `ListQuery` struct of a parsed model file and its named fields
fn list_query(file: &syn::File) -> Result<(&syn::ItemStruct, &syn::FieldsNamed), String> {
    let list = file.items.iter().find_map(|item| match item {
        syn::Item::Struct(s) if s.ident == "ListQuery" => Some(s),
        _ => None,
    });
    let Some(list) = list else { return Err("no `ListQuery` struct".to_string()) };
    let syn::Fields::Named(fields) = &list.fields else { return Err("`ListQuery` is not a struct with named fields".to_string()) };
    Ok((list, fields))
}

// The column of the `near` filter of the `ListQuery` of the model file `source`, `embedding` for
// `#[sqlx_filter(column = "embedding", op = "nearest")] near: ...`, generated by the search of the model
pub(crate) fn near_column(source: &str) -> Result<String, String> {
    let file = parse_model_file(source)?;
    let (_, fields) = list_query(&file)?;
    let near = fields.named.iter().find(|f| f.ident.as_ref().is_some_and(|i| i == "near"));
    let Some(near) = near else { return Err("its `ListQuery` has no `near` filter, generated by the search of the model".to_string()) };
    near.attrs
        .iter()
        .map(|attr| &source[attr.span().byte_range()])
        .filter(|text| text.starts_with("#[sqlx_filter") && has_word(text, "nearest"))
        .find_map(|text| {
            let rest = &text[text.find("column")? + "column".len()..];
            let rest = rest.trim_start().strip_prefix('=')?.trim_start().strip_prefix('"')?;
            Some(rest[..rest.find('"')?].to_string())
        })
        .ok_or_else(|| "the `near` field of its `ListQuery` is not a `#[sqlx_filter(column = \"...\", op = \"nearest\")]`".to_string())
}

// Checks that the model `model` of the model file `source` has a field `column` of type `pgvector::Vector`,
// optional or not, the vector the relation reads from the parent and compares to the ones of the children.
// It is looked for in `Recipe`, `NewRecipe` and `UpdatableRecipe`: a vector kept out of the responses is
// in the last two only
pub(crate) fn check_vector_column(source: &str, model: &str, column: &str) -> Result<(), String> {
    let file = parse_model_file(source)?;
    let ident = field_ident(column);
    let field = model_structs(&file, model)?
        .into_iter()
        .find_map(|(_, fields)| fields.named.iter().find(|f| f.ident.as_ref().is_some_and(|i| *i == ident)));
    let Some(field) = field else { return Err(format!("`{}` has no field `{}`", model, column)) };
    let ty = &source[field.ty.span().byte_range()];
    // `Option<Vector>` when the model imports `pgvector::Vector`
    if !is_dense_vector(ty) && !is_dense_vector(&ty.replace("Vector", "pgvector::Vector")) {
        return Err(format!("`{}.{}` is a `{}`, not a `pgvector::Vector`", model, column, ty));
    }
    Ok(())
}

const NEAREST_TPL: &str = r#"
    // The application state, declared (or re-exported) at the root of the crate
    use crate::AppState;
    // The models, imported from the folders of src where they were found (side by side with the relation otherwise)
    {model_imports}
    use serde::{Deserialize, Serialize};
    use octopux::{
        HasMany,
        anyhow::Result,
        async_trait,
    };
    use octopux::pgvector::Vector;{openapi_imports}{graphql_imports}

    #[derive(Deserialize{openapi_derives})]
    pub struct {relation}Query {
        /// Number of rows to skip
        pub offset: Option<usize>,
        /// Maximum number of rows to return (20 by default, 100 at most)
        pub limit: Option<usize>,
        /// The least similarity of the {children}, from -1 to 1 (none by default)
        pub min_similarity: Option<f64>,
        /// The columns to sort by, separated by commas, a column prefixed with `-` in descending order: `{sort_example}`.
        /// Among {sort_columns_doc}, `-similarity` by default, the most similar first
        pub sort: Option<String>,
        /// The direction of the columns not prefixed with `-`, `asc` (by default) or `desc`: alone, the direction of the similarity
        pub order: Option<String>,
    }

    /// Number of {children} returned when no limit is given
    const DEFAULT_LIMIT: i64 = 20;
    /// Maximum number of {children} returned
    const MAX_LIMIT: i64 = 100;
    /// The columns the {children} can be sorted by: their similarity, and the columns of the {child_table}
    const SORT_COLUMNS: &[&str] = &[{sort_columns}];

    /// A {child_lower_case} near to a {parent_lower_case}, and how similar: the cosine similarity of their vectors,
    /// 1 for the same meaning
    #[derive(Serialize{openapi_derives}{graphql_derive}, sqlx::FromRow)]
    pub struct {relation}Result {
        pub similarity: f64,
        #[sqlx(flatten)]
        pub {child_field}: {child},
    }

    /// The {children} nearest to a {parent_lower_case} by their `{child_column}`, the most similar first unless `sort` tells otherwise,
    /// served on `GET /{parent_lower_case}/{id}/{relation_name}`
    pub struct {relation};

    #[async_trait]
    impl HasMany for {relation} {
        type Parent = {parent};
        type Id = Id;
        type Query = {relation}Query;
        type Result = Vec<{relation}Result>;
        type State = AppState;
        const RELATION: &'static str = "{relation_name}";

        async fn list_related(id: Id, query: &{relation}Query, state: &AppState) -> Result<Option<Vec<{relation}Result>>> {
            // the vector of the {parent_lower_case}, None when it does not exist
            let parent: Option<(Option<Vector>,)> = sqlx::query_as("SELECT {column} FROM {parent_table} WHERE id = $1{live}")
                .bind(id)
                .fetch_optional(&state.pool)
                .await?;
            let Some((vector,)) = parent else { return Ok(None) };
            // a {parent_lower_case} saved without `{column}` is near to nothing
            let Some(vector) = vector else { return Ok(Some(Vec::new())) };
            // the most similar first by default, `order` alone reversing it
            let (sort, order) = match query.sort.as_deref() {
                Some(sort) => (sort, query.order.as_deref()),
                None => ("similarity", Some(query.order.as_deref().unwrap_or("desc"))),
            };
            // the similarity sorted by the cosine distance reversed, so that the HNSW index of `{child_column}` serves it,
            // then `id`, so that the pages neither overlap nor skip rows
            let terms = octopux::__private::sort_terms(Some(sort), order, SORT_COLUMNS)?
                .unwrap_or_default()
                .split(", ")
                .map(|term| match term {
                    "similarity ASC" => "({child_column} <=> $1) DESC",
                    "similarity DESC" => "({child_column} <=> $1) ASC",
                    term => term,
                })
                .collect::<Vec<_>>()
                .join(", ");
            let offset = query.offset.unwrap_or(0) as i64;
            let limit = query.limit.map_or(DEFAULT_LIMIT, |limit| (limit as i64).min(MAX_LIMIT));
            // the vector bound first, as $1: the {children} without `{child_column}` are near to nothing{exclusion}.
            // `min_similarity` filters before the pagination, so that the pages stay full
            let mut qb = sqlx::QueryBuilder::<sqlx::Postgres>::new("SELECT *, 1 - ({child_column} <=> ");
            qb.push_bind(vector).push(") AS similarity FROM {child_table} WHERE {child_live}{child_column} IS NOT NULL");{exclude_parent}
            if let Some(min) = query.min_similarity {
                qb.push(" AND 1 - ({child_column} <=> $1) >= ").push_bind(min);
            }
            qb.push(" ORDER BY ").push(terms).push(", id LIMIT ").push_bind(limit).push(" OFFSET ").push_bind(offset);
            Ok(Some(qb.build_query_as::<{relation}Result>().fetch_all(&state.pool).await?))
        }
    }

    // Registers the route of the {children} nearest to a {parent_lower_case}, to mount with `.configure({module}::configure)`
    // in the same scope as the {parent_lower_case} routes
    pub fn configure(cfg: &mut {service_config}) {
        {endpoint}!({relation})(cfg)
    }{graphql_resolver}
    "#;

// Resolver of the GraphQL field of the relation, called by the `#[ComplexObject]` of the parent
const NEAREST_GRAPHQL_RESOLVER: &str = r#"

    // Resolves the `{relation_name}` field of the GraphQL {parent} type, declared in the `#[ComplexObject]` of its model
    pub async fn resolve(
        ctx: &async_graphql::Context<'_>,
        id: Id,
        offset: Option<usize>,
        limit: Option<usize>,
        min_similarity: Option<f64>,
        sort: Option<String>,
        order: Option<String>,
    ) -> async_graphql::Result<Vec<{relation}Result>> {
        let state = ctx.data::<actix_web::web::Data<AppState>>()?;
        let nearest = {relation}::list_related(id, &{relation}Query { offset, limit, min_similarity, sort, order }, state.get_ref()).await?;
        // the parent was resolved, so it exists
        Ok(nearest.unwrap_or_default())
    }

    // The GraphQL query of the {children} nearest to a {parent_lower_case} (async-graphql), to merge into the query root of the schema:
    // `#[derive(MergedObject, Default)] struct Query({module}::{relation}RootQuery, ...);`
    #[derive(Default)]
    pub struct {relation}RootQuery;

    #[async_graphql::Object]
    impl {relation}RootQuery {
        /// The {children} nearest to the {parent_lower_case} `id`, the most similar first unless `sort` tells otherwise, as `GET /{parent_lower_case}/{id}/{relation_name}`
        async fn {root_field}(
            &self,
            ctx: &async_graphql::Context<'_>,
            id: Id,
            offset: Option<usize>,
            limit: Option<usize>,
            min_similarity: Option<f64>,
            sort: Option<String>,
            order: Option<String>,
        ) -> async_graphql::Result<Vec<{relation}Result>> {
            let state = ctx.data::<actix_web::web::Data<AppState>>()?;
            match {relation}::list_related(id, &{relation}Query { offset, limit, min_similarity, sort, order }, state.get_ref()).await? {
                Some(nearest) => Ok(nearest),
                None => Err(async_graphql::Error::new("ENTITY_NOT_FOUND")),
            }
        }
    }"#;

// Field of the relation in the `#[ComplexObject]` of the parent model
const NEAREST_GRAPHQL_FIELD: &str = r#"
        /// The {children} nearest to the {parent_lower_case}, the most similar first unless `sort` tells otherwise, paginated
        async fn {relation_name}(
            &self,
            ctx: &Context<'_>,
            offset: Option<usize>,
            limit: Option<usize>,
            min_similarity: Option<f64>,
            sort: Option<String>,
            order: Option<String>,
        ) -> async_graphql::Result<Vec<{relation_path}::{relation}Result>> {
            {relation_path}::resolve(ctx, self.id, offset, limit, min_similarity, sort, order).await
        }"#;

// The field of the query root listing the entities nearest to a parent: `similar_recipes` for the `similar`
// recipes of a recipe, `recipe_nearest_wines` for its wines
pub(crate) fn root_field(relation: &Relation) -> String {
    if relation.child_table == relation.parent_table {
        format!("{}_{}", relation.name, pluralize(&to_snake_case(&relation.child)))
    } else {
        format!("{}_{}", to_snake_case(&relation.parent), relation.name)
    }
}

// Merges the GraphQL query of the relation written in `path` into the query root of src/main.rs,
// printing it to merge by hand when src/main.rs was not bootstrapped with --graphql
pub(crate) fn add_query_root(root: &Path, path: &str, relation: &Relation) -> Result<(), Error> {
    let module = crate_module(root, Path::new(path))
        .and_then(|m| m.strip_prefix("crate::").map(String::from))
        .unwrap_or_else(|| relation.module());
    let query = format!("{}::{}RootQuery", module, relation.type_name());
    let main = source_path(root, None, "main.rs");
    let source = fs::read_to_string(root.join(&main)).ok();
    match source.as_deref().and_then(|source| with_merged_root(source, "Query", &query).map(|patched| (source, patched))) {
        Some((source, patched)) if patched == source => {
            println!("{}", success(&format!("The GraphQL query `{}` is already merged in {}", query, main)));
        }
        Some((_, patched)) => {
            fs::write(root.join(&main), patched)?;
            println!("{}", success(&format!("Merged `{}` into the query root of the schema in {}", query, main)));
        }
        None => println!("{}", highlight(&format!("  Merge `{}` into the query root of the async-graphql schema", query))),
    }
    Ok(())
}

// `paths` are the modules as imported from the parent model
pub(crate) fn nearest_graphql_field(relation: &Relation, paths: &ModulePaths) -> String {
    NEAREST_GRAPHQL_FIELD
        .replace("{children}", &pluralize(&to_snake_case(&relation.child)))
        .replace("{parent_lower_case}", &relation.parent.to_lowercase())
        .replace("{relation_name}", &relation.name)
        .replace("{relation_path}", &paths.relation)
        .replace("{relation}", &relation.type_name())
}

// `paths` are the modules as imported from the relation, `timestamps` skips the soft deleted parent and children.
// The children are sorted by their similarity, or by the columns of `relation.sort`
pub(crate) fn render_nearest_relation(relation: &Relation, nearest: &Nearest, paths: &ModulePaths, openapi: bool, graphql: bool, timestamps: bool) -> String {
    let (openapi_imports, openapi_derives, service_config, endpoint) = if openapi {
        (
            "\n    use apistos::ApiComponent;\n    use schemars::JsonSchema;\n    use octopux::gen_documented_relation_endpoint;",
            OPENAPI_DERIVES,
            "apistos::web::ServiceConfig",
            "gen_documented_relation_endpoint",
        )
    } else {
        ("\n    use octopux::gen_relation_endpoint;", "", "actix_web::web::ServiceConfig", "gen_relation_endpoint")
    };
    let (graphql_imports, graphql_derive) = if graphql { ("\n    use async_graphql::SimpleObject;", ", SimpleObject") } else { ("", "") };
    let child = &relation.child;
    // a self relation leaves the parent out, and its children have the id of the parent
    let self_relation = relation.child_table == relation.parent_table;
    let (model_imports, exclusion, exclude_parent) = if self_relation {
        (
            format!("use {}::{{{}, Id}};", paths.parent, relation.parent),
            ", and the parent is left out",
            "\n            qb.push(\" AND id <> \").push_bind(id);",
        )
    } else {
        (format!("use {}::{{{}, Id}};\n    use {}::{};", paths.parent, relation.parent, paths.child, child), "", "")
    };
    // `id` is always a sort column, read from the child model when the relation was not given its columns
    let columns: Vec<&str> = if relation.sort.is_empty() { vec!["id"] } else { relation.sort.iter().map(String::as_str).collect() };
    let sort_columns = std::iter::once("\"similarity\"".to_string()).chain(columns.iter().map(|c| format!("\"{}\"", c))).collect::<Vec<_>>().join(", ");
    let sort_columns_doc = std::iter::once("`similarity`".to_string()).chain(columns.iter().map(|c| format!("`{}`", c))).collect::<Vec<_>>().join(", ");
    let sort_example = match columns.iter().find(|c| **c != "id") {
        Some(column) => format!("-similarity,{}", column),
        None => "-similarity,id".to_string(),
    };
    NEAREST_TPL
        .replace("{model_imports}", &model_imports)
        .replace("{openapi_imports}", openapi_imports)
        .replace("{openapi_derives}", openapi_derives)
        .replace("{graphql_imports}", graphql_imports)
        .replace("{graphql_derive}", graphql_derive)
        .replace("{graphql_resolver}", if graphql { NEAREST_GRAPHQL_RESOLVER } else { "" })
        .replace("{root_field}", &root_field(relation))
        .replace("{service_config}", service_config)
        .replace("{endpoint}", endpoint)
        .replace("{exclusion}", exclusion)
        .replace("{exclude_parent}", exclude_parent)
        .replace("{live}", if timestamps { " AND deleted_at IS NULL" } else { "" })
        .replace("{child_live}", if timestamps { "deleted_at IS NULL AND " } else { "" })
        .replace("{sort_columns_doc}", &sort_columns_doc)
        .replace("{sort_columns}", &sort_columns)
        .replace("{sort_example}", &sort_example)
        .replace("{column}", &nearest.column)
        .replace("{child_column}", &nearest.child_column)
        .replace("{parent_table}", &relation.sql_table(&relation.parent_table))
        .replace("{child_table}", &relation.sql_table(&relation.child_table))
        .replace("{child_field}", &field_ident(&to_snake_case(child)))
        .replace("{children}", &pluralize(&to_snake_case(child)))
        .replace("{child_lower_case}", &child.to_lowercase())
        .replace("{relation}", &relation.type_name())
        .replace("{relation_name}", &relation.name)
        .replace("{module}", &relation.module())
        .replace("{parent_lower_case}", &relation.parent.to_lowercase())
        .replace("{parent}", &relation.parent)
        .replace("{child}", child)
}

// HNSW index of the vector column of the child, which every page of the relation is ordered by, the index
// the migration of the model creates for its vectors, so that it is not created twice
pub(crate) fn render_nearest_migration(relation: &Relation, nearest: &Nearest) -> String {
    format!(
        "CREATE INDEX IF NOT EXISTS {t}_{c}_idx ON {q} USING hnsw ({c} vector_cosine_ops);\n",
        t = relation.child_table,
        c = nearest.child_column,
        q = relation.sql_table(&relation.child_table)
    )
}

// Asks, after the search of a model, whether it serves the entities nearest to one of them too
pub(crate) fn read_similar<R: BufRead, W: Write>(input: &mut R, output: &mut W, entity: &str) -> Result<bool, Error> {
    let path = entity.to_lowercase();
    let message = format!("Serve the {} nearest to a {} too, on `GET /{}/{{id}}/similar`?", pluralize(&to_snake_case(entity)), path, path);
    confirm(input, output, &message)
}

// The `similar` relation of a searched model to its other entities nearest to it by the vector of its search,
// proposed with the search by `generate-model` and `add-field`, written next to the model
pub(crate) struct Similar {
    relation: Relation,
    files: RelationFiles,
}

impl Similar {
    // `model` is the path of the model file, `field` the vector of its search
    pub(crate) fn new(model: &str, entity: &str, table: &str, schema: Option<&str>, field: &str) -> Similar {
        let relation = Relation::new(entity.to_string(), entity.to_string(), Some(default_name(entity, entity)), None, None, None)
            .with_tables(Some(table.to_string()), Some(table.to_string()), None)
            .with_schema(schema.map(String::from))
            .with_nearest(Some(Nearest { column: field.to_string(), child_column: field.to_string() }));
        let model = PathBuf::from(model);
        let files = RelationFiles { relation: model.with_file_name(format!("{}.rs", relation.module())), parent: model.clone(), child: model };
        Similar { relation, files }
    }

    // The file of the relation, `src/recipe_similar.rs`
    pub(crate) fn path(&self) -> String {
        self.files.relation.display().to_string()
    }

    // Writes the relation once the model is written, sorted by the columns of the model,
    // and adds its field to the GraphQL type of the model
    pub(crate) fn write(&self, root: &Path, openapi: bool, graphql: bool, timestamps: bool) -> Result<(), Error> {
        let Some(nearest) = &self.relation.nearest else { return Ok(()) };
        let path = self.path();
        let paths = ModulePaths::from_file(root, &self.files.relation, &self.files);
        let model = self.files.child.display().to_string();
        let relation = match fs::read_to_string(root.join(&model)).map_err(|e| e.to_string()).and_then(|source| sort_columns(&source, &self.relation.child)) {
            Ok(columns) => self.relation.clone().with_sort(columns),
            Err(e) => {
                println!("{}", warning(&format!("The columns of {} not read from {} ({}), the {} are sorted by `similarity` and `id` only", self.relation.child, model, e, pluralize(&to_snake_case(&self.relation.child)))));
                self.relation.clone()
            }
        };
        write_source(&path, &render_nearest_relation(&relation, nearest, &paths, openapi, graphql, timestamps))?;
        let module = self.relation.module();
        println!(
            "{}",
            success(&format!("Generated the {} nearest to a {} in {}, {}", pluralize(&to_snake_case(&self.relation.child)), self.relation.parent.to_lowercase(), path, declaration_hint(root, &path, &module)))
        );
        println!("{}", highlight(&format!("  Mount it with `.configure({}::configure)` in the scope of the {} routes", module, self.relation.parent.to_lowercase())));
        if graphql {
            add_relation_field(root, &self.files, &self.relation)?;
            add_query_root(root, &path, &self.relation)?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::search::{with_search, with_search_field, Search, EMBEDDING_MODELS};
    use crate::{render_model, with_header, Dialect, Field};

    fn model() -> String {
        let fields = [Field { name: "title".into(), ty: "String".into(), references: None, unique: false, length: None }];
        let source = with_header("//", &render_model("Recipe", true, true, true, true, &fields, Dialect::Postgres));
        let vector = Field { name: "embedding".into(), ty: "Option<pgvector::Vector>".into(), references: None, unique: false, length: Some(384) };
        let search = Search { field: "embedding".into(), text: vec![("title".into(), false)], model: &EMBEDDING_MODELS[0] };
        let source = with_search_field(&source, "Recipe", &vector).unwrap();
        with_search(&source, "Recipe", &search, "pgvector::Vector").unwrap()
    }

    fn relation(parent: &str, child: &str) -> Relation {
        Relation::new(parent.into(), child.into(), Some(default_name(parent, child)), None, None, None)
    }

    #[test]
    fn the_route_is_named_after_the_child() {
        assert_eq!(default_name("Recipe", "Recipe"), "similar");
        assert_eq!(default_name("Recipe", "WineBottle"), "nearest_wine_bottles");
    }

    #[test]
    fn the_column_of_the_child_is_the_one_of_its_near_filter() {
        assert_eq!(near_column(&model()).unwrap(), "embedding");
        let without = with_header("//", &render_model("Recipe", false, false, true, true, &[], Dialect::Postgres));
        assert!(near_column(&without).unwrap_err().contains("no `near` filter"));
    }

    #[test]
    fn the_column_of_the_parent_is_a_vector_of_its_model() {
        assert_eq!(check_vector_column(&model(), "Recipe", "embedding"), Ok(()));
        assert!(check_vector_column(&model(), "Recipe", "embeding").unwrap_err().contains("has no field `embeding`"));
        assert!(check_vector_column(&model(), "Recipe", "title").unwrap_err().contains("not a `pgvector::Vector`"));
        let imported = model().replace("pub embedding: Option<pgvector::Vector>", "pub embedding: Option<Vector>");
        assert_eq!(check_vector_column(&imported, "Recipe", "embedding"), Ok(()));
    }

    #[test]
    fn a_self_relation_lists_the_others_nearest_to_the_parent() {
        let rel = relation("Recipe", "Recipe").with_schema(Some("app".into()));
        let nearest = Nearest { column: "embedding".into(), child_column: "embedding".into() };
        let rel = rel.with_sort(vec!["title".into()]);
        let rendered = render_nearest_relation(&rel, &nearest, &ModulePaths::siblings(&rel), true, true, true);
        syn::parse_file(&rendered).unwrap();
        for expected in [
            "use super::recipe::{Recipe, Id};",
            "#[derive(Serialize, JsonSchema, ApiComponent, SimpleObject, sqlx::FromRow)]\n    pub struct RecipeSimilarResult {\n        pub similarity: f64,\n        #[sqlx(flatten)]\n        pub recipe: Recipe,\n    }",
            "impl HasMany for RecipeSimilar {",
            "type Result = Vec<RecipeSimilarResult>;",
            "const RELATION: &'static str = \"similar\";",
            "sqlx::query_as(\"SELECT embedding FROM app.recipe WHERE id = $1 AND deleted_at IS NULL\")",
            "const SORT_COLUMNS: &[&str] = &[\"similarity\", \"id\", \"title\"];",
            "/// Among `similarity`, `id`, `title`, `-similarity` by default, the most similar first",
            "\"similarity DESC\" => \"(embedding <=> $1) ASC\",",
            "qb.push_bind(vector).push(\") AS similarity FROM app.recipe WHERE deleted_at IS NULL AND embedding IS NOT NULL\");\n            qb.push(\" AND id <> \").push_bind(id);",
            "qb.push(\" AND 1 - (embedding <=> $1) >= \").push_bind(min);",
            "qb.push(\" ORDER BY \").push(terms).push(\", id LIMIT \")",
            "gen_documented_relation_endpoint!(RecipeSimilar)(cfg)",
            "&RecipeSimilarQuery { offset, limit, min_similarity, sort, order }",
            "pub struct RecipeSimilarRootQuery;",
            "async fn similar_recipes(",
            "None => Err(async_graphql::Error::new(\"ENTITY_NOT_FOUND\")),",
        ] {
            assert!(rendered.contains(expected), "`{}` missing from\n{}", expected, rendered);
        }
        let field = nearest_graphql_field(&rel, &ModulePaths::siblings(&rel));
        assert!(field.contains("-> async_graphql::Result<Vec<super::recipe_similar::RecipeSimilarResult>>"), "{}", field);
        assert!(field.contains("super::recipe_similar::resolve(ctx, self.id, offset, limit, min_similarity, sort, order).await"), "{}", field);
        assert_eq!(render_nearest_migration(&rel, &nearest), "CREATE INDEX IF NOT EXISTS recipe_embedding_idx ON app.recipe USING hnsw (embedding vector_cosine_ops);\n");
    }

    #[test]
    fn a_relation_to_another_model_keeps_its_children() {
        let rel = relation("Recipe", "Wine");
        let nearest = Nearest { column: "embedding".into(), child_column: "taste".into() };
        let rendered = render_nearest_relation(&rel, &nearest, &ModulePaths::siblings(&rel), false, false, false);
        syn::parse_file(&rendered).unwrap();
        assert!(rendered.contains("use super::recipe::{Recipe, Id};\n    use super::wine::Wine;"), "{}", rendered);
        assert!(rendered.contains("SELECT embedding FROM recipe WHERE id = $1\""), "{}", rendered);
        // the parent is not a wine, none is left out, and the soft deletes are not filtered without timestamps
        assert!(rendered.contains("qb.push_bind(vector).push(\") AS similarity FROM wine WHERE taste IS NOT NULL\");\n            if let Some(min)"), "{}", rendered);
        assert!(rendered.contains("const SORT_COLUMNS: &[&str] = &[\"similarity\", \"id\"];"), "{}", rendered);
        assert!(rendered.contains("const RELATION: &'static str = \"nearest_wines\";"), "{}", rendered);
        assert_eq!(root_field(&rel), "recipe_nearest_wines");
        assert!(!rendered.contains("apistos") && !rendered.contains("async_graphql"), "{}", rendered);
    }
}
